   if g[r][c] and (r,c) not in seen:
    st=[(r,c)]; seen.add((r,c)); cells=[]
    while st:
     y,x=st.pop(); cells.append((y,x))
     for dy in (-1,0,1):
      for dx in (-1,0,1):
       q=(y+dy,x+dx)
       if (dy or dx) and 0<=q[0]<h and 0<=q[1]<w and g[q[0]][q[1]] and q not in seen: seen.add(q); st.append(q)
    out.append(cells)
 return out
